  line-height: 1.7;
}
.hbt-img-counter {
  font-size: 11px;
  color: var(--hbt-muted);
  margin-top: 4px;
}

/* 轮播箭头 */
.hbt-carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: rgba(5, 8, 18, 0.55);
  border: 1px solid var(--hbt-button-border);
  color: var(--hbt-accent-strong);
  font-size: 14px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
