  font-size: 13px;
  color: var(--hbt-tag);
  cursor: default;
}
.hbt-tag:hover { color: var(--hbt-tag-hover); }

/* 底部：日期+点赞 */
.hbt-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 12px;
  border-top: 1px solid var(--hbt-divider);
