  margin-top: 10px;
  letter-spacing: 0.08em;
}
.hbt-comment-section-header:first-child { margin-top: 0; }

.hbt-comment-item {
  display: flex;
  gap: 10px;
  padding: 10px 12px;
  margin-bottom: 8px;
  background: var(--hbt-panel-bg);
  border: 1px solid var(--hbt-panel-border);
