/* 响应式 */
@media (max-width: 400px) {
  body { padding: 12px; }
  .hbt-card { padding: 14px; border-radius: 18px; }
  .hbt-header { padding-right: 162px; }
  .hbt-card-controls { top: 14px; right: 14px; gap: 8px; }
  .hbt-theme-switcher { gap: 5px; padding: 4px 5px; }
  .hbt-theme-btn { width: 26px; height: 26px; font-size: 11px; }
  .hbt-img-slide { min-height: 120px; padding: 18px 14px; }
