<body>
<div id="hbt-app"></div>
<textarea id="hbt-raw-source" hidden>$1</textarea>
<script>
var HBT_KEYS = new Set(['author', 'handle', 'zone', 'title', 'img', 'body', 'tags', 'date', 'likes', 'hot', 'reply', 'pin']);
var HBT_THEMES = [
  { id: 'moon', label: '寒', title: '寒月宫' },
  { id: 'jade', label: '阙', title: '天庭玉阙' },
  { id: 'night', label: '夜', title: '幽夜秘境' },
];
var HBT_THEME_STORAGE_KEY = 'hbt-theme';
var HBT_DEFAULT_THEME = 'moon';
var hbtEventsBound = false;

function hashBase(str) {
  var hash = 0;
  for (var i = 0; i < str.length; i++) {
    hash = str.charCodeAt(i) + ((hash << 5) - hash);
  }
  return Math.abs(hash % 360);
}

function hashColor(str) {
  return 'hsl(' + hashBase(str) + ', 60%, 45%)';
}

function hashGradient(str) {
  var h1 = hashBase(str);
  var h2 = (h1 + 40) % 360;
  return 'linear-gradient(135deg, hsl(' + h1 + ',60%,40%), hsl(' + h2 + ',70%,50%))';
}

function firstChar(str) {
  return str ? str.charAt(0) : '?';
}

function createNode(tagName, className, text) {
  var node = document.createElement(tagName);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

function isValidHBTTheme(theme) {
  return theme === 'moon' || theme === 'jade' || theme === 'night';
}

function readStoredHBTTheme() {
  try {
    var theme = window.localStorage.getItem(HBT_THEME_STORAGE_KEY);
    return isValidHBTTheme(theme) ? theme : HBT_DEFAULT_THEME;
  } catch (error) {
    return HBT_DEFAULT_THEME;
  }
}

function writeStoredHBTTheme(theme) {
  if (!isValidHBTTheme(theme)) return;

  try {
    window.localStorage.setItem(HBT_THEME_STORAGE_KEY, theme);
  } catch (error) {
    // Ignore storage failures inside constrained environments.
  }
}

function appendAvatar(parent, className, name, background, isSmall) {
  var avatar = createNode('div', className, firstChar(name));
  avatar.style.background = background;
  if (isSmall) {
    avatar.style.width = '24px';
    avatar.style.height = '24px';
    avatar.style.fontSize = '11px';
  }
  parent.appendChild(avatar);
}

function buildHBTThemeSwitcher(activeTheme) {
  var switcher = createNode('div', 'hbt-theme-switcher');

  for (var i = 0; i < HBT_THEMES.length; i++) {
    var theme = HBT_THEMES[i];
    var button = createNode('button', 'hbt-theme-btn' + (theme.id === activeTheme ? ' is-active' : ''), theme.label);
    button.type = 'button';
    button.dataset.themeOption = theme.id;
    button.setAttribute('aria-label', theme.title);
    button.setAttribute('aria-pressed', theme.id === activeTheme ? 'true' : 'false');
    button.title = theme.title;
    switcher.appendChild(button);
  }

  return switcher;
}

function applyHBTTheme(card, theme) {
  if (!card) return;

  var nextTheme = isValidHBTTheme(theme) ? theme : HBT_DEFAULT_THEME;
  card.dataset.theme = nextTheme;

  var buttons = card.querySelectorAll('.hbt-theme-btn');
  for (var i = 0; i < buttons.length; i++) {
    var isActive = buttons[i].dataset.themeOption === nextTheme;
    buttons[i].classList.toggle('is-active', isActive);
    buttons[i].setAttribute('aria-pressed', isActive ? 'true' : 'false');
  }
}

function applyHBTThemeToCards(theme, root) {
  var scope = root || document;
  var nextTheme = isValidHBTTheme(theme) ? theme : HBT_DEFAULT_THEME;
  var cards = scope.querySelectorAll('.hbt-card');

  for (var i = 0; i < cards.length; i++) {
    applyHBTTheme(cards[i], nextTheme);
  }

  writeStoredHBTTheme(nextTheme);
}

function parseCommentField(value, type) {
  var colonIdx = value.indexOf(':');
  return {
    type: type,
    name: (colonIdx > 0 ? value.substring(0, colonIdx) : '').trim(),
    text: (colonIdx > 0 ? value.substring(colonIdx + 1) : value).trim(),
    replies: [],
  };
}

function parseRawPost(text) {
  var lines = text.split(/\r?\n/);
  var data = {
    author: '',
    handle: '',
    zone: 'public',
    title: '',
    images: [],
    body: '',
    tags: [],
    date: '',
    likes: '',
    comments: [],
  };
  var currentKey = null;
  var currentVal = [];
  var lastComment = null;

  function commitField() {
    if (!currentKey) return;
    var value = currentVal.join('\n').trim();
    if (!value) {
      currentKey = null;
      currentVal = [];
      return;
    }

    switch (currentKey) {
      case 'author':
        data.author = value;
        break;
      case 'handle':
        data.handle = value;
        break;
      case 'zone':
        data.zone = value.toLowerCase() === 'private' ? 'private' : 'public';
        break;
      case 'title':
        data.title = value;
        break;
      case 'img':
        data.images.push(value);
        break;
      case 'body':
        data.body = value;
        break;
      case 'tags':
        data.tags = value.match(/#[^\s#]+/g) || [value];
        break;
      case 'date':
        data.date = value;
        break;
      case 'likes':
        data.likes = value;
        break;
      case 'hot':
      case 'pin':
        lastComment = parseCommentField(value, currentKey);
        data.comments.push(lastComment);
        break;
      case 'reply':
        if (lastComment) {
          lastComment.replies.push(parseCommentField(value, 'reply'));
        }
        break;
    }

    currentKey = null;
    currentVal = [];
  }

  for (var i = 0; i < lines.length; i++) {
    var trimmed = lines[i].trim();
    if (!trimmed) continue;

    var colonIdx = trimmed.indexOf(':');
    if (colonIdx > 0) {
      var candidateKey = trimmed.slice(0, colonIdx);
      if (HBT_KEYS.has(candidateKey)) {
        commitField();
        currentKey = candidateKey;
        currentVal.push(trimmed.slice(colonIdx + 1));
        continue;
      }
    }

    if (currentKey) currentVal.push(trimmed);
  }

  commitField();
  return data;
}

function stringValue(value) {
  if (value === undefined || value === null) return '';
  return String(value).trim();
}

function toList(value) {
  if (Array.isArray(value)) {
    var items = [];
    for (var i = 0; i < value.length; i++) {
      var item = stringValue(value[i]);
      if (item) items.push(item);
    }
    return items;
  }

  var single = stringValue(value);
  return single ? [single] : [];
}

function normalizeComment(comment, fallbackType) {
  if (!comment || typeof comment !== 'object') return null;

  var normalized = {
    type: comment.type === 'pin' ? 'pin' : (fallbackType === 'pin' ? 'pin' : 'hot'),
    name: stringValue(comment.name || comment.author || comment.user),
    text: stringValue(comment.text || comment.body || comment.content || comment.message),
    replies: [],
  };

  if (!normalized.name || !normalized.text) return null;

  if (Array.isArray(comment.replies)) {
    for (var i = 0; i < comment.replies.length; i++) {
      var reply = normalizeComment(comment.replies[i], 'reply');
      if (reply) {
        reply.type = 'reply';
        normalized.replies.push(reply);
      }
    }
  }

  return normalized;
}

function normalizePostData(source) {
  if (!source || typeof source !== 'object') return null;

  var data = {
    author: stringValue(source.author || source.name),
    handle: stringValue(source.handle),
    zone: stringValue(source.zone).toLowerCase() === 'private' ? 'private' : 'public',
    title: stringValue(source.title),
    images: [],
    body: stringValue(source.body || source.content || source.text),
    tags: [],
    date: stringValue(source.date),
    likes: stringValue(source.likes),
    comments: [],
  };

  data.images = toList(source.images || source.img);
  data.tags = toList(source.tags);

  if (Array.isArray(source.comments)) {
    for (var i = 0; i < source.comments.length; i++) {
      var comment = normalizeComment(source.comments[i]);
      if (comment) data.comments.push(comment);
    }
  }

  var hotComments = Array.isArray(source.hot) ? source.hot : (source.hot ? [source.hot] : []);
  var pinComments = Array.isArray(source.pin) ? source.pin : (source.pin ? [source.pin] : []);

  for (var j = 0; j < hotComments.length; j++) {
    var hot = normalizeComment(hotComments[j], 'hot');
    if (hot) data.comments.push(hot);
  }

  for (var k = 0; k < pinComments.length; k++) {
    var pin = normalizeComment(pinComments[k], 'pin');
    if (pin) data.comments.push(pin);
  }

  if (!data.author && !data.title && !data.body && !data.images.length) {
    return null;
  }

  return data;
}

function buildCommentGroup(label, comments) {
  if (!comments.length) return null;

  var fragment = document.createDocumentFragment();
  fragment.appendChild(createNode('div', 'hbt-comment-section-header', label));

  for (var i = 0; i < comments.length; i++) {
    var comment = comments[i];
    var item = createNode('div', 'hbt-comment-item');
    appendAvatar(item, 'hbt-comment-avatar', comment.name, hashColor(comment.name), false);

    var content = createNode('div', 'hbt-comment-content');
    content.appendChild(createNode('span', 'hbt-commenter-name', comment.name));
    content.appendChild(createNode('span', 'hbt-comment-text', comment.text));
    item.appendChild(content);
    fragment.appendChild(item);

    for (var j = 0; j < comment.replies.length; j++) {
      var reply = comment.replies[j];
      var replyWrap = createNode('div', 'hbt-reply-item');
      var replyItem = createNode('div', 'hbt-comment-item');
      appendAvatar(replyItem, 'hbt-comment-avatar', reply.name, hashColor(reply.name), true);

      var replyContent = createNode('div', 'hbt-comment-content');
      replyContent.appendChild(createNode('span', 'hbt-reply-prefix', '↳'));
      replyContent.appendChild(createNode('span', 'hbt-commenter-name', reply.name));
      replyContent.appendChild(createNode('span', 'hbt-comment-text', reply.text));
      replyItem.appendChild(replyContent);
      replyWrap.appendChild(replyItem);
      fragment.appendChild(replyWrap);
    }
  }

  return fragment;
}

function buildHBTCard(data) {
  var initialTheme = readStoredHBTTheme();
  var card = createNode('div', 'hbt-card hbt-card-collapsed');
  card.dataset.theme = initialTheme;

  var controls = createNode('div', 'hbt-card-controls');
  controls.appendChild(buildHBTThemeSwitcher(initialTheme));

  var toggleButton = createNode('button', 'hbt-toggle-btn', '展开');
  toggleButton.type = 'button';
  toggleButton.setAttribute('aria-expanded', 'false');
  controls.appendChild(toggleButton);
  card.appendChild(controls);

  var header = createNode('div', 'hbt-header');
  appendAvatar(header, 'hbt-avatar', data.author, hashGradient(data.author), false);

  var authorInfo = createNode('div', 'hbt-author-info');
  authorInfo.appendChild(createNode('div', 'hbt-author-name', data.author));
  if (data.handle) {
    authorInfo.appendChild(createNode('div', 'hbt-handle', data.handle));
  }
  header.appendChild(authorInfo);
  card.appendChild(header);

  card.appendChild(
    createNode(
      'div',
      'hbt-zone ' + (data.zone === 'private' ? 'hbt-zone-private' : 'hbt-zone-public'),
      data.zone === 'private' ? '🔒 私人区' : '🌐 公共区'
    )
  );

  if (data.title) {
    card.appendChild(createNode('div', 'hbt-title', data.title));
  }

  var expandable = createNode('div', 'hbt-expandable');

  if (data.images.length) {
    var carousel = createNode('div', 'hbt-carousel');
    carousel.dataset.activeIndex = '0';
    var inner = createNode('div', 'hbt-carousel-inner');

    for (var i = 0; i < data.images.length; i++) {
      var slide = createNode('div', 'hbt-img-slide' + (i === 0 ? ' hbt-slide-active' : ''));
      slide.appendChild(createNode('span', 'hbt-img-icon', '🖼️'));
      slide.appendChild(createNode('span', 'hbt-img-desc', data.images[i]));
      slide.appendChild(createNode('span', 'hbt-img-counter', (i + 1) + ' / ' + data.images.length));
      inner.appendChild(slide);
    }

    if (data.images.length > 1) {
      var prevBtn = createNode('button', 'hbt-carousel-btn hbt-carousel-prev', '‹');
      prevBtn.type = 'button';
      prevBtn.setAttribute('aria-label', '上一张');
      inner.appendChild(prevBtn);

      var nextBtn = createNode('button', 'hbt-carousel-btn hbt-carousel-next', '›');
      nextBtn.type = 'button';
      nextBtn.setAttribute('aria-label', '下一张');
      inner.appendChild(nextBtn);
    }

    carousel.appendChild(inner);
    expandable.appendChild(carousel);
  }

  if (data.body) {
    expandable.appendChild(createNode('div', 'hbt-body', data.body));
  }

  if (data.tags.length) {
    var tags = createNode('div', 'hbt-tags');
    for (var j = 0; j < data.tags.length; j++) {
      tags.appendChild(createNode('span', 'hbt-tag', data.tags[j]));
    }
    expandable.appendChild(tags);
  }

  if (data.date || data.likes) {
    var footer = createNode('div', 'hbt-footer');
    footer.appendChild(createNode('span', 'hbt-date', data.date));
    footer.appendChild(createNode('span', 'hbt-likes', '❤️ ' + data.likes));
    expandable.appendChild(footer);
  }

  if (data.comments.length) {
    var comments = createNode('div', 'hbt-comments');
    var pins = [];
    var hots = [];

    for (var k = 0; k < data.comments.length; k++) {
      if (data.comments[k].type === 'hot') hots.push(data.comments[k]);
      else pins.push(data.comments[k]);
    }

    var pinGroup = buildCommentGroup('📌 顶置评论', pins);
    var hotGroup = buildCommentGroup('🔥 热门评论', hots);
    if (pinGroup) comments.appendChild(pinGroup);
    if (hotGroup) comments.appendChild(hotGroup);
    expandable.appendChild(comments);
  }

  card.appendChild(expandable);
  applyHBTTheme(card, initialTheme);
  return card;
}

function updateHBTCardExpansion(card, expanded) {
  var button = card.querySelector('.hbt-toggle-btn');
  if (!button) return;

  card.classList.toggle('hbt-card-collapsed', !expanded);
  button.textContent = expanded ? '收起' : '展开';
  button.setAttribute('aria-expanded', expanded ? 'true' : 'false');
}

function hbtGoSlide(carousel, nextIndex) {
  var slides = carousel.querySelectorAll('.hbt-img-slide');
  if (!slides.length) return;

  var activeSlide = carousel.querySelector('.hbt-slide-active');
  if (activeSlide) activeSlide.classList.remove('hbt-slide-active');
  slides[nextIndex].classList.add('hbt-slide-active');
  carousel.dataset.activeIndex = String(nextIndex);
}

function bindHBTEvents() {
  if (hbtEventsBound) return;

  document.addEventListener('click', function(event) {
    var themeButton = event.target.closest('.hbt-theme-btn');
    if (themeButton) {
      var theme = themeButton.dataset.themeOption;
      if (!isValidHBTTheme(theme)) return;

      applyHBTThemeToCards(theme, document);
      return;
    }

    var toggleButton = event.target.closest('.hbt-toggle-btn');
    if (toggleButton) {
      var card = toggleButton.closest('.hbt-card');
      if (!card) return;

      updateHBTCardExpansion(card, card.classList.contains('hbt-card-collapsed'));
      return;
    }

    var button = event.target.closest('.hbt-carousel-btn');
    if (!button) return;

    var carousel = button.closest('.hbt-carousel');
    if (!carousel) return;

    var slides = carousel.querySelectorAll('.hbt-img-slide');
    if (slides.length < 2) return;

    var currentIndex = Number(carousel.dataset.activeIndex || 0);
    var delta = button.classList.contains('hbt-carousel-prev') ? -1 : 1;
    hbtGoSlide(carousel, (currentIndex + delta + slides.length) % slides.length);
  });

  hbtEventsBound = true;
}

function getMessageScopedVariables() {
  try {
    var getMessageId = typeof getCurrentMessageId === 'function'
      ? getCurrentMessageId
      : (window.parent && typeof window.parent.getCurrentMessageId === 'function'
        ? window.parent.getCurrentMessageId.bind(window.parent)
        : null);
    var getMessageVariables = typeof getVariables === 'function'
      ? getVariables
      : (window.parent && typeof window.parent.getVariables === 'function'
        ? window.parent.getVariables.bind(window.parent)
        : null);

    if (!getMessageId || !getMessageVariables) return null;

    var messageId = getMessageId();
    if (!messageId) return null;

    return getMessageVariables({ type: 'message', message_id: messageId });
  } catch (error) {
    return null;
  }
}

function getVariableBackedPostData() {
  var variables = getMessageScopedVariables();
  if (!variables || typeof variables !== 'object') return null;

  var candidates = [
    variables.huangbaotian,
    variables.hbt,
    variables.raw_huangbaotian,
    variables.raw_hbt,
  ];

  for (var i = 0; i < candidates.length; i++) {
    var candidate = candidates[i];

    if (typeof candidate === 'string' && candidate.trim()) {
      return parseRawPost(candidate);
    }

    var normalized = normalizePostData(candidate);
    if (normalized) return normalized;
  }

  return null;
}

function getEmbeddedRawPostData(scope) {
  var source = scope.querySelector('#hbt-raw-source');
  if (!source) return null;

  var text = '';
  if ('value' in source && typeof source.value === 'string') {
    text = source.value.trim();
  } else {
    text = source.textContent.trim();
  }
  return text ? parseRawPost(text) : null;
}

function renderHBT(root) {
  var scope = root || document;
  var app = scope.querySelector('#hbt-app');

  if (app && !app.dataset.hbtRendered) {
    var appData = getVariableBackedPostData() || getEmbeddedRawPostData(scope);
    app.dataset.hbtRendered = 'true';

    if (appData) {
      app.textContent = '';
      app.appendChild(buildHBTCard(appData));
    }
  }

  var raws = scope.querySelectorAll('.hbt-raw:not([data-hbt-rendered])');

  for (var i = 0; i < raws.length; i++) {
    var raw = raws[i];
    raw.dataset.hbtRendered = 'true';
    raw.insertAdjacentElement('afterend', buildHBTCard(parseRawPost(raw.textContent)));
  }
}

function initHBT() {
  bindHBTEvents();
  renderHBT(document);
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initHBT, { once: true });
} else {
  initHBT();
}
</script>
</body>
