function countImages(char){

  let n = 0;

  char.sections.forEach(section => {

    section.groups.forEach(group => {

      group.variants.forEach(variant => {

        n += variant.count;

      });

    });

  });

  return n;
}


/* =========================================================
   生成图片列表
   ========================================================= */

function buildList(
  char,
  section,
  group,
  variant
){

  const list = [];

  for(
    let i = 1;
    i <= variant.count;
    i++
  ){

    const rel =
      `${section.type}/${char.id}/${group.key}/${variant.key}/${i}`;

    list.push({

      src:
        `${IMG_BASE}/${rel}.png`,

      path:
        `${rel}.png`,

      label:
        `${char.name} · ${group.label} · ${variant.label}`

    });

  }

  return list;
}


