    const card =
      document.createElement(
        'div'
      );

    card.className =
      'char-card';


    card.innerHTML = `

      <div class="char-cover">

        <img
          src="${char.cover}"
          alt="${char.name}"
          draggable="false">

      </div>


      <div class="char-overlay">

        <div class="char-name">
