        <div class="char-en">
          ${char.subtitle}
        </div>

        <div class="char-num">
          ${countImages(char)} 张
        </div>

      </div>

    `;


    const img =
      card.querySelector(
        'img'
      );


    img.addEventListener(
      'error',
      () => {

        img.style.opacity = '0';

      }
    );


    card.addEventListener(
      'click',
      () => {

        openGallery(char);

      }
    );


    grid.appendChild(card);

  });


  document
    .getElementById('totalCount')
    .textContent =

    CHARACTERS.reduce(
      (sum,char) =>
        sum + countImages(char),
      0
    );

}


