      '.char-scroll'
    );


  if(sc){

    sc.scrollTop = 0;

  }

}


/* =========================================================
   构筑完整图鉴
   ========================================================= */

function buildGallery(char){

  const body =
    document.getElementById(
      'galleryBody'
    );

  body.innerHTML = '';


  char.sections.forEach(section => {

    const sec =
      document.createElement(
        'section'
      );


    sec.className =
      'section' +
      (
        section.type === 'NSFW'
          ? ' nsfw'
          : ''
      );


    const head =
      document.createElement(
        'div'
      );


    head.className =
      'section-head';


    head.innerHTML = `

      <span class="section-bar"></span>

      <span>
        ${section.title}
      </span>

      <span class="section-tag">
        ${section.type}
      </span>

    `;


    sec.appendChild(head);


    section.groups.forEach(group => {

      const gHead =
        document.createElement(
          'div'
        );


      gHead.className =
        'group-head';


      gHead.textContent =
        group.label;


      sec.appendChild(
        gHead
      );


      group.variants.forEach(
        variant => {

          sec.appendChild(

            buildVariantBlock(
              char,
              section,
              group,
              variant
            )

          );

        }
      );

    });


    body.appendChild(sec);

  });

}


/* =========================================================
   构筑每个情境
   ========================================================= */

function buildVariantBlock(
  char,
  section,
  group,
  variant
){

  const block =
    document.createElement(
      'div'
    );


  block.className =
    'variant-block';


  const head =
    document.createElement(
      'div'
    );


  head.className =
    'variant-head';


  head.innerHTML = `

    <span class="variant-label">
      ${variant.label}
    </span>

    <span class="variant-meta">
      ${variant.count} 张
    </span>

  `;


  block.appendChild(head);


  /*
   * 这里已经从横向 thumb-row
   * 改成真正的 Grid。
   */

  const row =
    document.createElement(
      'div'
    );


  row.className =
    'thumb-row';


  const list =
    buildList(
      char,
      section,
      group,
      variant
    );


  list.forEach(
    (item,idx) => {

      const card =
        document.createElement(
          'div'
        );


      card.className =
        'thumb loading';


      const img =
        document.createElement(
          'img'
        );


      img.src =
        item.src;


      img.alt =
        `${variant.label} ${idx + 1}`;


      img.loading =
        'lazy';


      img.draggable =
        false;


      img.addEventListener(
        'load',
        () => {

          card.classList.remove(
            'loading'
          );

        }
      );


      img.addEventListener(
        'error',
        () => {

          card.classList.remove(
            'loading'
          );

          card.classList.add(
            'error'
          );

        }
      );


      const idxTag =
        document.createElement(
          'span'
        );


      idxTag.className =
        'thumb-idx';


      idxTag.textContent =
        String(
          idx + 1
        ).padStart(
          2,
          '0'
        );


      card.appendChild(
        img
      );


      card.appendChild(
        idxTag
      );


      card.addEventListener(
        'click',
        () => {

          openLightbox(
            list,
            idx
          );

        }
      );


      row.appendChild(
        card
      );

    }
  );


  block.appendChild(
    row
  );


  return block;
}


