/* 关闭 */

function closeLightbox(){

  lightbox.classList.remove(
    'active'
  );

  lbImg.src = '';

}


/* 显示当前 */

function renderLightbox(){

  if(!lbList.length){
    return;
  }


  const item =
    lbList[lbIndex];


  lbImg.src =
    item.src;


  lbImg.alt =
    item.label;


  lbLabel.textContent =
    item.label;


  lbPath.textContent =
    item.path;


  lbCounter.textContent =

    `${String(
      lbIndex + 1
    ).padStart(2,'0')} / ${String(
      lbList.length
    ).padStart(2,'0')}`;


  lbImg.style.animation =
    'none';


  void lbImg.offsetWidth;


  lbImg.style.animation =
    '';

}


/* 上一张 */

function lbPrev(){

  if(!lbList.length){
    return;
  }


  lbIndex =

    (
      lbIndex - 1 +
      lbList.length
    )
    % lbList.length;


  renderLightbox();

}


/* 下一张 */

function lbNext(){

  if(!lbList.length){
    return;
  }


  lbIndex =

    (
      lbIndex + 1
    )
    % lbList.length;


  renderLightbox();

}


/* =========================================================
