        '疏影': 'shuying'
    };

    const BASE_URL =
        'https://raw.githubusercontent.com/2877810328/ImgStore/main/QingYueMaster';

    const parts =
        sceneText.split('|').map(item => item.trim());

    if (parts.length !== 5) {
        return;
    }

    const sceneType = parts[0];
    const character = parts[1];
    const category = parts[2];
    const mood = parts[3];
    const number = parts[4];

    const characterKey = characterMap[character];

    if (!characterKey) {
        return;
    }

    const imageUrl =
        BASE_URL + '/' + sceneType + '/' + characterKey + '/' + category + '/' + mood + '/' + number + '.png';

    const container = document.getElementById('qm-portrait');
    const upper = document.getElementById('qm-upper');

    if (!container || !upper) {
        return;
    }

    container.innerHTML = `
        <img
            src="${imageUrl}"
            alt="${character}"
            onerror="this.style.display='none';"
        >
    `;

})();
</script>


